package servicio;
import api.publica.PagoClienteDTO.*;import config.ConfiguracionMercadoPago;import dao.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.*;import java.util.*;import negocio.*;import pagos.*;
public class ConsultaOrdenPagoClienteService {private final OrdenPagoDAO dao;private final Clock clock;private final PasarelaPagoOnline pasarela;private final AcreditacionOrdenPagoTransaccionalService acreditacion;public ConsultaOrdenPagoClienteService(){this(new OrdenPagoDAOMySQL(),Clock.systemDefaultZone(),PasarelaPagoFactory.crear(ConfiguracionMercadoPago.cargar()),new AcreditacionOrdenPagoTransaccionalService());}public ConsultaOrdenPagoClienteService(OrdenPagoDAO d,Clock c){this(d,c,new PasarelaPagoNoDisponible("Conciliacion no configurada."),null);}public ConsultaOrdenPagoClienteService(OrdenPagoDAO d,Clock c,PasarelaPagoOnline p,AcreditacionOrdenPagoTransaccionalService a){if(d==null||c==null||p==null)throw new IllegalArgumentException("Las dependencias son obligatorias.");dao=d;clock=c;pasarela=p;acreditacion=a;}public OrdenPagoPublica convertir(OrdenPago o){if(o==null)return null;long restantes=o.getFechaExpiracion()==null?0:Math.max(0,Duration.between(LocalDateTime.now(clock),o.getFechaExpiracion()).toSeconds());boolean manual=o.getMetodo()==MetodoOrdenPago.TRANSFERENCIA_MANUAL;boolean reintento=Set.of(EstadoOrdenPago.RECHAZADA,EstadoOrdenPago.ERROR,EstadoOrdenPago.EXPIRADA).contains(o.getEstado());String mensaje=switch(o.getEstado()){case ESPERANDO_VERIFICACION->"El complejo verificará la transferencia desde la administración.";case ESPERANDO_PAGO->"Completá el pago para confirmar la cancha.";case PROCESANDO->"Estamos verificando la acreditación.";case APROBADA->"El pago fue acreditado.";case RECHAZADA->"El pago no pudo acreditarse.";case EXPIRADA->"La orden de pago venció.";default->"Estado de pago actualizado.";};return new OrdenPagoPublica(o.getId(),o.getReservaId(),o.getProveedor().name(),o.getMetodo().name(),o.getEstado().name(),o.getImporte(),o.getMoneda(),o.getFechaExpiracion(),restantes,!manual&&o.getEstado()==EstadoOrdenPago.ESPERANDO_PAGO,manual&&o.getEstado()==EstadoOrdenPago.ESPERANDO_VERIFICACION,reintento,!o.getEstado().esTerminal(),checkoutSeguro(o,restantes),mensaje);}private String checkoutSeguro(OrdenPago o,long restantes){if(o.getMetodo()!=MetodoOrdenPago.PAGO_ONLINE||o.getEstado()!=EstadoOrdenPago.ESPERANDO_PAGO||restantes<=0||o.getUrlPago()==null||o.getUrlPago().isBlank())return null;try{java.net.URI uri=java.net.URI.create(o.getUrlPago());return "https".equalsIgnoreCase(uri.getScheme())&&uri.getHost()!=null?uri.toString():null;}catch(RuntimeException e){return null;}}public HistorialOrdenes historial(long reservaId){return new HistorialOrdenes(reservaId,dao.listarPorReserva(reservaId).stream().map(this::conciliar).map(this::convertir).toList());}public OrdenPago conciliar(OrdenPago o){if(o==null||o.getProveedor()!=ProveedorPago.MERCADO_PAGO||o.getReferenciaExterna()==null||o.getEstado().esTerminal()||!pasarela.disponible()||acreditacion==null)return o;List<PagoExterno> encontrados=pasarela.buscarPagosPorReferencia(o.getReferenciaExterna());if(encontrados==null)return o;List<PagoExterno> aprobados=encontrados.stream().filter(PagoExterno::aprobado).filter(p->compatible(o,p)).sorted(Comparator.comparing(PagoExterno::fechaAprobacion,Comparator.nullsLast(Comparator.naturalOrder())).thenComparing(PagoExterno::pagoId,Comparator.nullsLast(String::compareTo))).toList();if(aprobados.isEmpty())return o;PagoExterno pago=aprobados.getFirst();EventoPago e=new EventoPago();e.setOrdenPagoId(o.getId());e.setProveedor(ProveedorPago.MERCADO_PAGO);e.setEventoExternoId("reconciliation:payment:"+pago.pagoId()+":"+pago.estado());e.setTipo("payment.reconciled");e.setFirmaValida(true);e.setPayloadHash(hash(o.getReferenciaExterna()+":"+pago.pagoId()+":"+pago.estado()));e.setPayloadJson("{\"source\":\"reconciliation\"}");acreditacion.procesarAprobacion(e,pago.pagoId());dao.asociarPagoExterno(o.getId(),pago.pagoId());OrdenPago actual=dao.buscar(o.getId());return actual==null?o:actual;}private boolean compatible(OrdenPago o,PagoExterno p){return p!=null&&o.getReferenciaExterna().equals(p.referencia())&&p.importe()!=null&&p.importe().compareTo(o.getImporte())==0&&p.moneda()!=null&&p.moneda().equalsIgnoreCase(o.getMoneda());}private String hash(String value){try{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}